/*
 * ext_table.c -- the table that says, for each of the 65,536 opcode words, which extension words follow it.
 *
 * One byte per opcode: (src_mode << 4) | dst_mode, the modes being those of ext_t in pjit.c: EXT_NONE=0, EXT_I16=1, EXT_I32=2, EXT_D8_XAREG=3, EXT_D16_PC=4,
 * EXT_D8_XPC=5, EXT_BDISP=6 (source only: the displacement of Bcc / BRA.W, minus 2). The source nibble describes the <ea> that is read, or whose address is computed
 * (LEA, PEA, JSR, JMP), the destination nibble the <ea> that is written; MOVEM's register-list mask counts as a source immediate. A destination is never PC-relative.
 *
 * The table is maintained by hand. tests/qemu/smoke_ext_audit.c and tools/gen/check/block_test.py check it.
 */
